import{_ as d}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as i,c as o,o as e,af as r,b as l,w as a,a as s,G as h,ag as c}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const P=JSON.parse('{"title":"技术地图：依赖驱动的知识地图","description":"全站技术主线入口（v6）——模型生命周期与系统工程两条链在 Inference 汇合，读世界与写世界分离，协议按连接方向分组；十个组按依赖排序，按症状两跳进入正确的组。","frontmatter":{"title":"技术地图：依赖驱动的知识地图","description":"全站技术主线入口（v6）——模型生命周期与系统工程两条链在 Inference 汇合，读世界与写世界分离，协议按连接方向分组；十个组按依赖排序，按症状两跳进入正确的组。","domain":"tech","tags":["tech","orientation","map"],"navOrder":1,"topicId":"tech-map","layer":"0","status":"canonical","nodeType":"resource","owner":"learn-ai","externalOwners":[],"prerequisites":[],"next":["complexity-ladder","site-boundaries","model-lifecycle-bridge"],"specVersion":"","lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"zh/tech/index.md","filePath":"zh/tech/index.md","lastUpdated":1788317563000}'),g={name:"zh/tech/index.md"};function E(f,t,p,u,b,A){const n=i("Mermaid");return e(),o("div",null,[t[1]||(t[1]=r('<blockquote><p><strong>所在组</strong>：层 0 · 方向与边界 ｜ <strong>上一组出口</strong>：无 ｜ <strong>本页出口</strong>：能定位问题域、说出它的依赖与出口，并进入正确的组 <strong>前置</strong>：无（全站入口） ｜ <strong>下一步</strong>：<a href="./00-map/complexity-ladder.html">复杂度决策阶梯</a> · <a href="./00-map/site-boundaries.html">站点边界与知识 ownership</a> · <a href="./01-model-lifecycle/">模型生命周期（桥接）</a></p></blockquote><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p><strong>结论先讲</strong>：这是一张<strong>依赖驱动的知识地图</strong>。v6 的组织逻辑不是「按技术名词分类」，而是回答三个结构性问题：</p><ol><li><strong>两条链在哪汇合</strong>——模型生命周期链（数据 → 预训练 → 后训练）与 AI 系统工程链（接入 → 上下文 → 接地/行动 → …）在 <strong>Inference</strong> 处汇合：你写的每一行 AI 应用代码都从左链的末端开始。左链的深层原理归 <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a>，右链是本仓 canonical 主线。</li><li><strong>读世界与写世界为什么分开</strong>——Grounding（检索、引用、更新）与 Action（工具、执行、权限）都是「让模型接触模型之外的东西」，但失败模式相反：读的失败是<strong>答错</strong>，写的失败是<strong>搞坏</strong>。验收口径因此不同（引用正确 vs 权限受限），分组成 <a href="./04-grounding/">04-grounding</a> 与 <a href="./05-action/">05-action</a>。</li><li><strong>协议为什么按连接方向分组</strong>——MCP、A2A、ACP、AG-UI 不是竞品而是各占一条连接方向（Agent↔工具、Agent↔Agent、编辑器↔coding agent、Agent↔UI）。选型第一问是「我要连的两边是什么」，不是「哪个协议更热」——见 <a href="./07-interoperability/">07-interoperability</a>。</li></ol><p>这张地图回答一个问题：<strong>你现在卡在哪，下一步去哪。</strong> 它不教你任何单项技术——每个组、每个主题都有自己的五段式章节（概述 → 使用 → 原理 → 开发 → 资料库）。</p><h3 id="心智模型-两链汇合-读写分离" tabindex="-1">心智模型：两链汇合，读写分离 <a class="header-anchor" href="#心智模型-两链汇合-读写分离" aria-label="Permalink to &quot;心智模型：两链汇合，读写分离&quot;">​</a></h3>',6)),(e(),l(c,null,{default:a(()=>[h(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20ML%5B%22%E6%A8%A1%E5%9E%8B%E7%94%9F%E5%91%BD%E5%91%A8%E6%9C%9F%E9%93%BE%20%E2%80%94%E2%80%94%20%E6%B7%B1%E5%B1%82%E5%8E%9F%E7%90%86%E5%BD%92%20Learn%20LLM%22%5D%0A%20%20%20%20%20%20%20%20M1%5B%22Data%20%2F%20Pretraining%22%5D%20--%3E%20M2%5B%22Post-training%3Cbr%2F%3ESFT%20%C2%B7%20RLHF%20%C2%B7%20PEFT%22%5D%0A%20%20%20%20end%0A%20%20%20%20M2%20%3D%3D%3E%20INF%5B%22Inference%3Cbr%2F%3E%E4%B8%A4%E9%93%BE%E5%9C%A8%E6%AD%A4%E6%B1%87%E5%90%88%22%5D%0A%20%20%20%20subgraph%20SE%5B%22AI%20%E7%B3%BB%E7%BB%9F%E5%B7%A5%E7%A8%8B%E9%93%BE%20%E2%80%94%E2%80%94%20%E6%9C%AC%E4%BB%93%20canonical%20%E4%B8%BB%E7%BA%BF%22%5D%0A%20%20%20%20%20%20%20%20INF%20--%3E%20C%5B%2202%20Inference%20%26%20Interface%3Cbr%2F%3E%E8%B0%83%E7%94%A8%E4%B8%8E%E4%BA%A7%E5%93%81%E6%8E%A5%E5%85%A5%22%5D%0A%20%20%20%20%20%20%20%20C%20--%3E%20CT%5B%2203%20Context%3Cbr%2F%3E%E8%BE%93%E5%85%A5%E8%BE%93%E5%87%BA%E5%8F%AF%E6%8E%A7%22%5D%0A%20%20%20%20%20%20%20%20CT%20--%3E%20G%5B%2204%20Grounding%20%E8%AF%BB%E4%B8%96%E7%95%8C%3Cbr%2F%3E%E6%A3%80%E7%B4%A2%20%C2%B7%20%E5%BC%95%E7%94%A8%20%C2%B7%20%E6%9B%B4%E6%96%B0%22%5D%0A%20%20%20%20%20%20%20%20CT%20--%3E%20A%5B%2205%20Action%20%E5%86%99%E4%B8%96%E7%95%8C%3Cbr%2F%3E%E5%B7%A5%E5%85%B7%20%C2%B7%20%E6%89%A7%E8%A1%8C%20%C2%B7%20%E6%9D%83%E9%99%90%22%5D%0A%20%20%20%20%20%20%20%20G%20--%3E%20AG%5B%2206%20Agent%20Systems%3Cbr%2F%3E%E8%BF%90%E8%A1%8C%E6%97%B6%20%C2%B7%20%E7%8A%B6%E6%80%81%20%C2%B7%20%E5%8D%8F%E4%BD%9C%22%5D%0A%20%20%20%20%20%20%20%20A%20--%3E%20AG%0A%20%20%20%20%20%20%20%20AG%20--%3E%20IOP%5B%2207%20Interoperability%3Cbr%2F%3E%E5%8D%8F%E8%AE%AE%E6%8C%89%E8%BF%9E%E6%8E%A5%E6%96%B9%E5%90%91%22%5D%0A%20%20%20%20%20%20%20%20IOP%20--%3E%20P%5B%2208%20Production%3Cbr%2F%3E%E8%AF%81%E6%8D%AE%20%C2%B7%20%E7%89%88%E6%9C%AC%E8%BD%B4%20%C2%B7%20%E8%BF%90%E7%BB%B4%22%5D%0A%20%20%20%20end%0A%20%20%20%20P%20-.%20%22%E8%A7%82%E6%B5%8B%20%C2%B7%20%E5%8F%8D%E9%A6%88%20%C2%B7%20%E7%89%88%E6%9C%AC%E6%BC%94%E8%BF%9B%22%20.-%3E%20ML%0A%20%20%20%20ADV%5B%2209%20Advanced%EF%BC%88%E6%A1%A5%E6%8E%A5%EF%BC%89%3Cbr%2F%3E%E5%8F%AF%E8%A7%A3%E9%87%8A%E6%80%A7%20%C2%B7%20%E6%8E%A8%E7%90%86%20%C2%B7%20%E5%89%8D%E6%B2%BF%E6%9E%B6%E6%9E%84%20%C2%B7%20%E5%A4%9A%E6%A8%A1%E6%80%81%22%5D%20-.%20%E6%B7%B1%E6%B0%B4%E5%8C%BA%E6%8C%89%E9%9C%80%E8%B7%B3%E8%BD%AC%20.-%3E%20ML%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[s(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=r('<p>箭头表示<strong>默认的依赖顺序</strong>，不是硬性运行时约束：一个 RAG 服务可以只经过 02/03/04，一个工具脚本可以只经过 02/03/05。实现永远回退到满足验收的最低复杂度。</p><h3 id="十组导航表" tabindex="-1">十组导航表 <a class="header-anchor" href="#十组导航表" aria-label="Permalink to &quot;十组导航表&quot;">​</a></h3><p>表中组按组号排序（00 → 09），主线之外的三类出口（附录/实战手册/资料库）殿后：</p><table tabindex="0"><thead><tr><th>组</th><th>回答什么问题</th><th>核心主题</th><th>依赖</th><th>出口</th></tr></thead><tbody><tr><td><a href="./00-map/complexity-ladder.html">00-map</a> 方向与地图</td><td>我该从哪开始、哪些不在本仓？</td><td>地图、复杂度阶梯、站点边界</td><td>无</td><td>能定位问题域与下一入口</td></tr><tr><td><a href="./01-model-lifecycle/">01-model-lifecycle</a> 模型生命周期（桥接）</td><td>手里的模型从哪来、影响我什么决策？</td><td>SFT / RLHF / PEFT 的工程影响</td><td>00</td><td>知道何时 prompt 不够、深水区去 Learn LLM 哪章</td></tr><tr><td><a href="./02-inference-interface/">02-inference-interface</a> 推理与接口</td><td>怎么把一次模型调用接进产品？</td><td>model-api、流式、结构化输出、会话与 UI、端侧</td><td>00–01</td><td>可取消、可观测的端到端交互</td></tr><tr><td><a href="./03-context/">03-context</a> 上下文</td><td>怎么让输入输出可控？</td><td>prompt、上下文工程、会话记忆</td><td>02</td><td>能写并验证 schema，知道失败验收</td></tr><tr><td><a href="./04-grounding/">04-grounding</a> 知识接地（读世界）</td><td>回答怎么有据？</td><td>嵌入与检索、RAG、高级检索</td><td>02–03</td><td>可追溯的检索链与可重跑的更新管道</td></tr><tr><td><a href="./05-action/">05-action</a> 行动（写世界）</td><td>怎么安全地执行动作？</td><td>工具调用契约、工具执行工程</td><td>03</td><td>权限受限、幂等且可撤销的动作</td></tr><tr><td><a href="./06-agent-systems/">06-agent-systems</a> Agent 系统</td><td>多步、可恢复、需审批的自主行为怎么做？</td><td>运行时、工作流、多 Agent、skills、状态与恢复</td><td>04–05</td><td>能限制权限、暂停/恢复任务</td></tr><tr><td><a href="./07-interoperability/">07-interoperability</a> 互操作</td><td>跨边界怎么连？</td><td>MCP / A2A / ACP / AG-UI 按连接方向</td><td>05–06</td><td>按连接方向选协议并说清不选其余的理由</td></tr><tr><td><a href="./08-production/">08-production</a> 生产与运营</td><td>怎么证明可上线并持续运行？</td><td>测试、评估、可观测、安全、成本、部署、版本轴</td><td>02–06</td><td>五类证据齐备，五轴可回滚可追溯</td></tr><tr><td><a href="./09-advanced/">09-advanced</a> 进阶（桥接）</td><td>深水区去哪学？</td><td>可解释性、推理与 TTC、MoE 与前沿架构、多模态</td><td>按需</td><td>知道停止点与跳转 Learn LLM 的章节</td></tr><tr><td><a href="./appendices/">附录区</a></td><td>还有什么可读？</td><td>训练桥接、案例、课程笔记、方法论存档</td><td>不参与主线顺序</td><td>主线之外的有位置阅读</td></tr><tr><td><a href="./../cookbook/">实战手册</a></td><td>按任务抄什么？</td><td>片段级代码配方</td><td>各组</td><td>打开就能抄</td></tr><tr><td><a href="./../resources.html">资料库</a></td><td>按问题找什么资源？</td><td>症状 → 章 → 资源的研究索引</td><td>各组</td><td>带着问题进来，带着下一问出去</td></tr></tbody></table><h3 id="症状驱动决策树" tabindex="-1">症状驱动决策树 <a class="header-anchor" href="#症状驱动决策树" aria-label="Permalink to &quot;症状驱动决策树&quot;">​</a></h3><p>从症状出发，不从名词出发。找到你的症状，直接进入对应的组：</p><table tabindex="0"><thead><tr><th>你的症状</th><th>去哪</th></tr></thead><tbody><tr><td>输出不稳定 / 无法解析</td><td><a href="./03-context/">03-context</a>（落点：<a href="./02-inference-interface/structured-output.html">结构化输出</a>）</td></tr><tr><td>回答稳定，但还没接入产品</td><td><a href="./02-inference-interface/">02-inference-interface</a></td></tr><tr><td>回答缺少私有或最新事实</td><td><a href="./04-grounding/">04-grounding</a></td></tr><tr><td>需要调用系统或执行动作</td><td><a href="./05-action/">05-action</a>；多步/可恢复/需审批再进 <a href="./06-agent-systems/">06-agent-systems</a></td></tr><tr><td>需要跨 host / 组织 / Agent 边界协作</td><td><a href="./07-interoperability/">07-interoperability</a>（按连接方向选择）</td></tr><tr><td>功能已跑，但不可证明 / 不可运营</td><td><a href="./08-production/">08-production</a></td></tr><tr><td>想懂模型内部 / 训练 / 前沿架构</td><td><a href="./01-model-lifecycle/">01-model-lifecycle</a> 与 <a href="./09-advanced/">09-advanced</a>（桥接 → Learn LLM）</td></tr></tbody></table><h3 id="本仓不教什么-三条边界" tabindex="-1">本仓不教什么（三条边界） <a class="header-anchor" href="#本仓不教什么-三条边界" aria-label="Permalink to &quot;本仓不教什么（三条边界）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>不在本仓展开</th><th>canonical owner</th><th>本仓保留什么</th></tr></thead><tbody><tr><td>模型内部机制：Transformer、训练数学、KV Cache 推导</td><td><a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a></td><td>决策影响 + 停止点 + 跳转，见<a href="./00-map/site-boundaries.html">站点边界</a></td></tr><tr><td>评估方法论：benchmark、judge、发布证据</td><td><a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">evals</a></td><td>何时需要证据 + 上线门如何接入</td></tr><tr><td>厂商 docs / blog 原文捕获与 EPUB 索引</td><td>sites-epub（<a href="https://epub.zenheart.site/" target="_blank" rel="noreferrer">epub.zenheart.site</a>）</td><td>跨厂商稳定概念的二次加工 + 阅读路线</td></tr></tbody></table><h3 id="何时使用-何时不用" tabindex="-1">何时使用 / 何时不用 <a class="header-anchor" href="#何时使用-何时不用" aria-label="Permalink to &quot;何时使用 / 何时不用&quot;">​</a></h3><ul><li>用：第一次进入本栏、不确定该学什么、或带着具体症状找入口。</li><li>不用：想了解模型内部机制（→ <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a>）；想找厂商产品的点击步骤（→ Products）；想要评估方法论（→ <a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">evals</a>）。</li></ul><p>历史版本里程碑：本地图于 2026-09 按 Issue #116 Scope v6 重构为<strong>十组依赖驱动</strong>结构（两链汇合 / 读写分离 / 协议按方向）；v5 的六层金字塔（能力变换链）叙事被本版取代，其「症状决策树 + 两跳演练 + 三站边界」被继承。更早的演变史未验证，不编造。</p><h2 id="_2-使用" tabindex="-1">2. 使用 <a class="header-anchor" href="#_2-使用" aria-label="Permalink to &quot;2. 使用&quot;">​</a></h2><p>本页是地图页，不产出运行产物；「使用」= 导航演练。验收标准只有一条：<strong>从症状出发，两次导航内进入正确的组。</strong></p><h3 id="演练-1-输出不稳定" tabindex="-1">演练 1：输出不稳定 <a class="header-anchor" href="#演练-1-输出不稳定" aria-label="Permalink to &quot;演练 1：输出不稳定&quot;">​</a></h3><ul><li><strong>症状</strong>：「模型返回的 JSON，十次里有三次解析失败。」</li><li><strong>第 1 跳</strong>：查上方决策树 → 「输出不稳定 / 无法解析」→ <a href="./03-context/">03-context</a>。</li><li><strong>第 2 跳</strong>：组内症状路由 → 输出形状问题的落点是<a href="./02-inference-interface/structured-output.html">结构化输出</a>（契约族页面，挂载在 02 组）。</li><li><strong>到达</strong>：读完能写并验证输出 schema，知道失败如何验收。</li></ul><h3 id="演练-2-回答缺最新事实" tabindex="-1">演练 2：回答缺最新事实 <a class="header-anchor" href="#演练-2-回答缺最新事实" aria-label="Permalink to &quot;演练 2：回答缺最新事实&quot;">​</a></h3><ul><li><strong>症状</strong>：「内部助手不知道我们上周更新的退款政策。」</li><li><strong>第 1 跳</strong>：决策树 → 「回答缺少私有或最新事实」→ <a href="./04-grounding/">04-grounding</a>。</li><li><strong>第 2 跳</strong>：组内主题表 → <a href="./04-grounding/rag.html">RAG</a>。</li><li><strong>到达</strong>：能构建可追溯的检索链和更新路径（读世界：失败模式是答错，不是搞坏）。</li></ul><h3 id="演练-3-想让系统动手" tabindex="-1">演练 3：想让系统动手 <a class="header-anchor" href="#演练-3-想让系统动手" aria-label="Permalink to &quot;演练 3：想让系统动手&quot;">​</a></h3><ul><li><strong>症状</strong>：「想让 Agent 自动把处理完的工单标记为已解决，怕它改错。」</li><li><strong>第 1 跳</strong>：决策树 → 「需要调用系统或执行动作」→ <a href="./05-action/">05-action</a>。</li><li><strong>第 2 跳</strong>：单次受控动作看<a href="./05-action/tool-execution.html">工具执行工程</a>；确认要多步、可恢复、需审批再进 <a href="./06-agent-systems/">Agent 运行时</a>。</li><li><strong>到达</strong>：能限制权限、把动作做成幂等且可撤销（写世界：验收口径是权限受限，不是引用正确）。</li></ul><p>三步都走不通时：先读<a href="./00-map/complexity-ladder.html">复杂度决策阶梯</a>确认你面对的需求等级，再回决策树。</p><h2 id="_3-原理" tabindex="-1">3. 原理 <a class="header-anchor" href="#_3-原理" aria-label="Permalink to &quot;3. 原理&quot;">​</a></h2><h3 id="为什么按依赖组织-而不是按分类学" tabindex="-1">为什么按依赖组织，而不是按分类学 <a class="header-anchor" href="#为什么按依赖组织-而不是按分类学" aria-label="Permalink to &quot;为什么按依赖组织，而不是按分类学&quot;">​</a></h3><p>旧目录曾把 Fundamentals（知识抽象）、Prompt（交互手段）、Integrate（实现方式）、RAG / Agent（架构模式）、Skills / MCP（资产/协议）、Engineering（生命周期）放在同一层——六种分类轴混用，读者无法从「我卡在哪」推到「我该读哪页」。本地图只保留一条主轴：<strong>知识按依赖排序，不按名词归类</strong>。每个组回答一个问题，标明依赖与出口；其余维度（信任域、生命周期、证据层级、ownership）降为页面元数据和对照表，不再竞争成顶级栏目。</p><h3 id="两链汇合-为什么第一条工程主题是接口而不是模型结构" tabindex="-1">两链汇合：为什么第一条工程主题是接口而不是模型结构 <a class="header-anchor" href="#两链汇合-为什么第一条工程主题是接口而不是模型结构" aria-label="Permalink to &quot;两链汇合：为什么第一条工程主题是接口而不是模型结构&quot;">​</a></h3><p>你的代码从 Inference 开始，不从 Transformer 开始。左链（模型生命周期）决定「手里的模型是什么、会什么」，右链（系统工程）决定「你用它造什么」——汇合点在 Inference / Model Interface。因此工程主线的第一组是<a href="./02-inference-interface/">推理与接口</a>，模型侧知识以<a href="./01-model-lifecycle/">桥接</a>形式挂在其上游。</p><h3 id="读写分离-两种相反的失败模式" tabindex="-1">读写分离：两种相反的失败模式 <a class="header-anchor" href="#读写分离-两种相反的失败模式" aria-label="Permalink to &quot;读写分离：两种相反的失败模式&quot;">​</a></h3><p>Grounding 与 Action 共享「让模型接触外部世界」这个直觉，但验收口径相反：读世界的失败是<strong>答错或该拒答没拒答</strong>（无副作用），验收引用正确与拒答正确；写世界的失败是<strong>破坏状态</strong>（有副作用），验收权限受限与可恢复。混在一组会让两套验收互相稀释——这是 04/05 分组的根因，也是「先检索后生成」与「先白名单后执行」两种工程直觉的同源结构。</p><h3 id="教学顺序不等于运行时依赖" tabindex="-1">教学顺序不等于运行时依赖 <a class="header-anchor" href="#教学顺序不等于运行时依赖" aria-label="Permalink to &quot;教学顺序不等于运行时依赖&quot;">​</a></h3><p>箭头代表新人默认的学习与依赖递进顺序。实际工程可以从契约和 fixture 自下而上实现；Grounding、Action、接口可按场景独立组合。每个组 index 同时标注「默认先学什么」和「哪些场景可以跳过」。</p><h2 id="_4-开发" tabindex="-1">4. 开发 <a class="header-anchor" href="#_4-开发" aria-label="Permalink to &quot;4. 开发&quot;">​</a></h2><p>本页不接代码；「开发」= 如何维护这张地图。</p><h3 id="维护流程" tabindex="-1">维护流程 <a class="header-anchor" href="#维护流程" aria-label="Permalink to &quot;维护流程&quot;">​</a></h3><ol><li><strong>注册</strong>：新主题先在 <code>_phase0/slug-map.json</code> 登记 topicId、组、slug 与 mergeSources；一个 topicId 只有一个 canonical owner。</li><li><strong>判组</strong>：按「本页回答什么问题、依赖谁、出口给谁」归组，不按技术名词归组。归不进任何组的，先问它是不是 Products / appendices / sibling 的内容。</li><li><strong>接线</strong>：新主题入组后，回本页核对：决策树是否需要新分支？十组表格的核心主题列是否要加词？</li><li><strong>双语</strong>：中英页 topicId、结构、结论、图、链接一一对应；<code>bilingualParity: exact</code> 才算完成。</li><li><strong>收尾</strong>：被合并的旧路径记入 <code>docs/public/redirects.json</code>，不留在侧栏。</li></ol><h3 id="盘点与验收" tabindex="-1">盘点与验收 <a class="header-anchor" href="#盘点与验收" aria-label="Permalink to &quot;盘点与验收&quot;">​</a></h3><ul><li>结构事实以 <code>node scripts/pyramid-inventory.mjs</code> 的输出为准，不以记忆为准；本页正文必须包含全部十个组目录名（00-map … 09-advanced）。</li><li>图谱级验收：从任一真实症状出发，两次导航内进入正确的组；任何孤立页面、无 owner 的协议页、只有链接没有问题上下文的资源卡，都算地图缺陷。</li></ul><h3 id="维护反模式" tabindex="-1">维护反模式 <a class="header-anchor" href="#维护反模式" aria-label="Permalink to &quot;维护反模式&quot;">​</a></h3><ul><li>用「更多 / More」收纳归不了类的页面——垃圾桶分类法会重新污染依赖主轴。</li><li>为热门协议新增顶层入口——协议永远从连接方向进入。</li><li>中英页各自演化——发现 <code>bilingualParity: partial</code> 超过一个写作周期即视为缺陷。</li></ul><h2 id="_5-资料库" tabindex="-1">5. 资料库 <a class="header-anchor" href="#_5-资料库" aria-label="Permalink to &quot;5. 资料库&quot;">​</a></h2><p>本页是入口，资料以「下一跳」为主。四级路线：</p><ul><li><strong>Beginner</strong>：读本页 + <a href="./00-map/complexity-ladder.html">复杂度决策阶梯</a>，能定位自己的组。</li><li><strong>Builder</strong>：进 <a href="./03-context/">03-context</a>、<a href="./02-inference-interface/">02-inference-interface</a>，完成第一个无密钥 fixture。</li><li><strong>Operator</strong>：进 <a href="./08-production/">08-production</a>，学会用证据与版本轴证明可上线。</li><li><strong>Researcher</strong>：下沉到 sibling 站点拿深层原理（<a href="./01-model-lifecycle/">01</a>、<a href="./09-advanced/">09</a> 的桥接页是入口）。</li></ul><h3 id="三站入口表" tabindex="-1">三站入口表 <a class="header-anchor" href="#三站入口表" aria-label="Permalink to &quot;三站入口表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>站点</th><th>canonical URL</th><th>用途</th><th>状态</th></tr></thead><tbody><tr><td>Learn LLM</td><td><a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">https://llm.zenheart.site/</a></td><td>模型内部机制、训练数学</td><td>HTTP 200（retrievedAt 2026-09-01）</td></tr><tr><td>Learn LLM 章节目录</td><td><a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/</a></td><td>21 章全书地图，deep-link 入口</td><td>HTTP 200（retrievedAt 2026-09-01）</td></tr><tr><td>evals</td><td><a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">https://evals.zenheart.site/</a></td><td>评估方法、benchmark、发布证据</td><td>HTTP 200（retrievedAt 2026-09-01）</td></tr><tr><td>sites-epub</td><td><a href="https://epub.zenheart.site/" target="_blank" rel="noreferrer">https://epub.zenheart.site/</a></td><td>厂商原文捕获与 EPUB 索引</td><td>warning：TLS 证书不匹配，HTTPS 当前不可达（retrievedAt 2026-09-01，引用前复核）</td></tr></tbody></table><p>各站分工细则、停止点与 bridge 元数据规范见<a href="./00-map/site-boundaries.html">站点边界与知识 ownership</a>。</p><h3 id="主动证伪与未决问题" tabindex="-1">主动证伪与未决问题 <a class="header-anchor" href="#主动证伪与未决问题" aria-label="Permalink to &quot;主动证伪与未决问题&quot;">​</a></h3><ul><li>若你发现某个症状在决策树上找不到分支，或某分支把你带进了错误的组——这是地图缺陷，优先修地图而不是绕过。</li><li>未决：sites-epub 当前 HTTPS 不可达（证书不匹配），其所有权声明暂按 bridge-register 记录，待恢复后复核。</li><li>未决：<a href="./05-action/">05-action</a>、<a href="./06-agent-systems/">06-agent-systems</a> 的组索引在 v6 迁移期间由并行任务补齐；在本页引用以组目录为准。</li></ul><h3 id="learn-ai-到此为止-继续去哪" tabindex="-1">learn-ai 到此为止 / 继续去哪 <a class="header-anchor" href="#learn-ai-到此为止-继续去哪" aria-label="Permalink to &quot;learn-ai 到此为止 / 继续去哪&quot;">​</a></h3><ul><li>模型怎么「想」：<a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a> 的<a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">章节目录</a>。</li><li>怎么证明效果好：<a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">evals</a>。</li><li>厂商原文与离线阅读：sites-epub（恢复后）。</li><li>本仓下一步：<a href="./00-map/complexity-ladder.html">复杂度决策阶梯</a>。</li></ul>',48))])}const _=d(g,[["render",E]]);export{P as __pageData,_ as default};
